<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <script src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js" integrity="sha384-..." crossorigin="anonymous"></script>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Times+New+Roman:wght@400;700&display=swap');

        body {
            font-family: 'Times New Roman', serif;
            margin: 2cm auto;
            padding: 0;
            max-width: 800px;
            background: white;
            line-height: 1.5;
            color: #000;
        }

        /* Page borders and margins simulation */
        @page {
            margin: 2cm;
        }

        h1, h2, h3 {
            font-family: 'Times New Roman', serif;
            font-weight: 700;
            text-align: center;
            margin-top: 1em;
            margin-bottom: 0.5em;
        }

        p {
            text-align: justify;
            margin-bottom: 0.8em;
        }

        .header {
            text-align: center;
            margin-bottom: 1em;
            border-bottom: 2px solid #000;
            padding-bottom: 0.5em;
        }

        .column {
            display: flex;
            gap: 2em;
            margin-bottom: 2em;
        }

        .left-column {
            width: 48%;
        }

        .right-column {
            width: 48%;
        }

        .image-placeholder {
            width: 100%;
            height: 200px;
            background: #f0f0f0;
            border: 1px solid #999;
            margin: 1em 0;
            display: flex;
            align-items: center;
            justify-content: center;
            text-align: center;
            font-style: italic;
            color: #666;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            margin: 1em 0;
        }

        th, td {
            border: 1px solid #000;
            padding: 0.5em;
            text-align: left;
        }

        ul, ol {
            margin-left: 2em;
            margin-bottom: 1em;
        }
    </style>
</head>
<body>

    <!-- Header simulation based on typical document layout -->
    <div class="header">
        <h1>Document Title</h1>
        <p><strong>Subtitle or Organization Name</strong></p>
    </div>

    <!-- Two-column layout example (common in reports, newspapers, flyers) -->
    <div class="column">
        <div class="left-column">
            <p>Left column text starts here. This is the first paragraph in the left column. The text flows naturally as it would in the original document image.</p>
            <p>Second paragraph in left column. Additional content placed to match the spatial distribution seen in the source.</p>
            <div class="image-placeholder">[Image: left column top]</div>
            <p>Third paragraph continuing the left column layout.</p>
        </div>
        <div class="right-column">
            <p>Right column text begins here. This is the first paragraph in the right column, positioned side-by-side with the left column as per the original spatial layout.</p>
            <p>Second paragraph in right column. Text is aligned to the right edge of its column.</p>
            <div class="image-placeholder">[Image: right column middle]</div>
            <p>Third paragraph in right column.</p>
        </div>
    </div>

    <!-- Single column continuation -->
    <p>Single column text below the two-column section. This text appears directly below the columns in the original document layout.</p>

    <!-- Unordered list example -->
    <ul>
        <li>List item 1 from the original document.</li>
        <li>List item 2 positioned exactly where it appears.</li>
        <li>List item 3.</li>
    </ul>

    <!-- Ordered list example -->
    <ol>
        <li>Numbered item 1.</li>
        <li>Numbered item 2.</li>
        <li>Numbered item 3.</li>
    </ol>

    <!-- Table example (common in reports) -->
    <table>
        <tr>
            <th>Column 1 Header</th>
            <th>Column 2 Header</th>
        </tr>
        <tr>
            <td>Row 1, Cell 1</td>
            <td>Row 1, Cell 2</td>
        </tr>
        <tr>
            <td>Row 2, Cell 1</td>
            <td>Row 2, Cell 2</td>
        </tr>
    </table>

    <!-- Placeholder for non-text element -->
    <div class="image-placeholder">[Chart: bottom center]</div>

    <!-- Footer simulation -->
    <div style="text-align: center; margin-top: 2em; border-top: 1px solid #000; padding-top: 0.5em;">
        Page 1 • Document ID or Date
    </div>

</body>
</html>
